"""MemuAI in Discord and WhatsApp: one command set and one chat engine for every messenger.

The platform adapters (``app.discord_bot``, ``app.whatsapp_bot``) only move text and buttons; everything a
user can do lives here, so Discord and WhatsApp behave the same:

* chat with MemuAI — the answers are generated by the same server-side jobs as the Telegram Mini App
  (``app.tgapp_chat``) and saved into the ordinary MemuAI chats, so the desktop window sees them;
* chats, models, a temporary chat, regenerate and stop;
* settings: web search, reasoning, personality, the bot language;
* pairing with a one-time code from MemuAI → Settings → Messengers. Until a person is paired nobody is
  served; afterwards only the paired person (and an optional short list of extra ids) is.

State is kept in ``memuai/messengers_state.json``: per platform the owner, the pairing code, the bot status
(written by the Proxy, read by the settings page) and the per-user selection (chat, model, toggles).
"""
from __future__ import annotations

import asyncio
import hashlib
import hmac
import json
import logging
import re
import secrets
import time
from dataclasses import dataclass, field
from typing import Any, Awaitable, Callable, Dict, List, Optional, Tuple

log = logging.getLogger("memuai.messengers")

PLATFORMS = ("discord", "whatsapp")
PAIR_TTL = 600
PAIR_ATTEMPTS = 6
PAIR_GLOBAL_ATTEMPTS = 20  # failed tries in total: the code burns (one stranger cannot grind it with many accounts)
PAIR_MAX_TRACKED = 64  # cap on the per-user attempt table
STREAM_EDIT_SECONDS = 1.3
LIST_PAGE = 10
TEMP_HISTORY = 40

# ---------------------------------------------------------------- state

def _path():
    from .pgdata import MEMU_DIR
    return MEMU_DIR / "messengers_state.json"


def _clean(raw: Any) -> Dict[str, Any]:
    data = raw if isinstance(raw, dict) else {}
    for name in PLATFORMS:
        part = data.get(name) if isinstance(data.get(name), dict) else {}
        part.setdefault("users", {})
        if not isinstance(part["users"], dict):
            part["users"] = {}
        data[name] = part
    return data


def load_state() -> Dict[str, Any]:
    try:
        return _clean(json.loads(_path().read_text(encoding="utf-8")))
    except (OSError, ValueError):
        return _clean({})


def update_state(mutator: Callable[[Dict[str, Any]], Any]) -> Dict[str, Any]:
    from .storage import mutate_json

    def merge(raw: Any):
        data = _clean(raw)
        result = mutator(data)
        return True, _clean(result if isinstance(result, dict) else data)

    return mutate_json(_path(), {}, merge, backup=False, validator=lambda value: isinstance(value, dict),
                       repair_invalid=True)


def public_status(platform: str) -> Dict[str, Any]:
    """What the settings page may see: no codes of other platforms, no user selections."""
    part = load_state().get(platform) or {}
    pairing = part.get("pairing") if isinstance(part.get("pairing"), dict) else {}
    alive = time.time() - float(part.get("heartbeat") or 0) < 100
    return {"status": part.get("status") or "off", "error": part.get("error") or "", "code": part.get("code") or "",
            "bot": part.get("bot") or {},
            "owner": part.get("owner") or {}, "alive": alive, "updated": part.get("heartbeat") or 0,
            # The pairing code itself is never stored or shown here: only its hash lives in the
            # shared state file, and the plaintext is shown once, in the answer to "pair".
            "pairing": {"expires": pairing.get("expires")}
            if pairing.get("code_hash") and float(pairing.get("expires") or 0) > time.time() else None,
            "webhook": part.get("webhook") or {}}


def set_status(platform: str, status: str, error: str = "", **extra: Any) -> None:
    def apply(data: Dict[str, Any]) -> None:
        part = data[platform]
        part.update({"status": status, "error": str(error or "")[:300], "heartbeat": time.time(),
                     "code": str(extra.pop("code", "") or "")[:40]})
        for key, value in extra.items():
            part[key] = value
    try:
        update_state(apply)
    except Exception:  # noqa: BLE001 - a status write must never break a bot
        log.debug("messenger status write failed", exc_info=True)


def _pair_hash(code: str, salt: str) -> str:
    return hashlib.sha256((salt + ":" + re.sub(r"[^A-Z0-9]", "", str(code or "").upper())).encode("utf-8")).hexdigest()


def new_pairing_code(platform: str) -> Dict[str, Any]:
    code = "".join(secrets.choice("ABCDEFGHJKLMNPQRSTUVWXYZ23456789") for _ in range(6))
    expires = time.time() + PAIR_TTL
    salt = secrets.token_hex(8)

    def apply(data: Dict[str, Any]) -> None:
        # Only the salted hash is stored (the shared state file is read by two processes);
        # the plaintext code is returned once, for the settings page to show.
        data[platform]["pairing"] = {"code_hash": _pair_hash(code, salt), "salt": salt,
                                     "expires": expires, "attempts": {}, "attempts_total": 0}
    update_state(apply)
    return {"code": code, "expires": expires}


def unpair(platform: str) -> None:
    def apply(data: Dict[str, Any]) -> None:
        data[platform]["owner"] = {}
        data[platform]["users"] = {}
        data[platform].pop("pairing", None)
    update_state(apply)


def try_pair(platform: str, user_id: str, name: str, code: str) -> Tuple[bool, str]:
    """Check a pairing code. Returns (paired, reason) — reason: ok · expired · wrong · locked · taken."""
    code = re.sub(r"[^A-Z0-9]", "", str(code or "").upper())[:12]
    outcome = {"ok": False, "reason": "wrong"}

    def apply(data: Dict[str, Any]) -> None:
        part = data[platform]
        pairing = part.get("pairing") if isinstance(part.get("pairing"), dict) else {}
        if not pairing.get("code_hash") or float(pairing.get("expires") or 0) < time.time():
            outcome["reason"] = "expired"
            return
        if int(pairing.get("attempts_total") or 0) >= PAIR_GLOBAL_ATTEMPTS:
            part.pop("pairing", None)  # burned by too many failures in total
            outcome["reason"] = "expired"
            return
        attempts = pairing.setdefault("attempts", {})
        tries = int(attempts.get(user_id) or 0)
        if tries >= PAIR_ATTEMPTS:
            outcome["reason"] = "locked"
            return
        if not hmac.compare_digest(_pair_hash(code, str(pairing.get("salt") or "")),
                                   str(pairing.get("code_hash") or "")):
            attempts[user_id] = tries + 1
            while len(attempts) > PAIR_MAX_TRACKED:
                attempts.pop(next(iter(attempts)), None)
            pairing["attempts_total"] = int(pairing.get("attempts_total") or 0) + 1
            if pairing["attempts_total"] >= PAIR_GLOBAL_ATTEMPTS:
                part.pop("pairing", None)  # burned by too many failures in total
                outcome["reason"] = "expired"
                return
            outcome["reason"] = "locked" if tries + 1 >= PAIR_ATTEMPTS else "wrong"
            return
        part["owner"] = {"id": user_id, "name": str(name or "")[:80], "since": time.time()}
        part.pop("pairing", None)
        outcome.update(ok=True, reason="ok")
    update_state(apply)
    return bool(outcome["ok"]), str(outcome["reason"])


def is_allowed(platform: str, user_id: str, prefs: Dict[str, Any]) -> bool:
    owner = (load_state().get(platform) or {}).get("owner") or {}
    if owner.get("id") and str(owner["id"]) == str(user_id):
        return True
    extra = prefs.get(f"{platform}_allowed_users") or []
    return bool(owner.get("id")) and str(user_id) in {str(x) for x in extra if x}


def user_state(platform: str, user_id: str) -> Dict[str, Any]:
    users = (load_state().get(platform) or {}).get("users") or {}
    row = users.get(str(user_id)) if isinstance(users.get(str(user_id)), dict) else {}
    return {"chat": "", "model": "", "temp": False, "temp_history": [], "web": None, "think": None, **row}


def save_user(platform: str, user_id: str, **changes: Any) -> Dict[str, Any]:
    def apply(data: Dict[str, Any]) -> None:
        users = data[platform]["users"]
        row = users.get(str(user_id)) if isinstance(users.get(str(user_id)), dict) else {}
        row.update(changes)
        if isinstance(row.get("temp_history"), list):
            row["temp_history"] = row["temp_history"][-TEMP_HISTORY:]
        users[str(user_id)] = row
    update_state(apply)
    return user_state(platform, user_id)

# ---------------------------------------------------------------- UI model

@dataclass
class Button:
    id: str
    label: str
    style: str = "secondary"  # primary · secondary · danger · success


@dataclass
class Choice:
    value: str
    label: str
    description: str = ""


@dataclass
class Card:
    """A message with optional buttons (rows) or one choice list. Adapters render it natively."""
    text: str
    buttons: List[List[Button]] = field(default_factory=list)
    choices: List[Choice] = field(default_factory=list)
    choice_id: str = ""
    placeholder: str = ""
    title: str = ""


class Adapter:
    """What a platform must provide. ``can_edit`` platforms get live streaming."""
    platform = ""
    limit = 2000
    can_edit = False

    async def send(self, peer: str, card: Card) -> Optional[str]:  # pragma: no cover - interface
        raise NotImplementedError

    async def edit(self, peer: str, message_id: str, card: Card) -> bool:  # pragma: no cover - interface
        return False

    async def typing(self, peer: str) -> None:
        return None

# ---------------------------------------------------------------- helpers

def tr(lang: str, ru: str, en: str) -> str:
    return en if lang == "en" else ru


def lang_of(platform: str, prefs: Dict[str, Any]) -> str:
    return "en" if str(prefs.get(f"{platform}_language") or prefs.get("language") or "ru") == "en" else "ru"


def split_text(text: str, limit: int) -> List[str]:
    """Split a long answer at paragraph, line or word borders; code fences are closed and reopened."""
    text = str(text or "").strip() or "…"
    out: List[str] = []
    fence = ""
    while text:
        if len(text) + len(fence) <= limit:
            out.append(fence + text)
            break
        room = limit - len(fence) - 8
        cut = max(text.rfind("\n\n", 0, room), text.rfind("\n", 0, room))
        if cut < room * 0.5:
            cut = text.rfind(" ", 0, room)
        if cut < room * 0.3:
            cut = room
        piece = fence + text[:cut].rstrip()
        opened = piece.count("```") % 2 == 1
        if opened:
            lang = re.findall(r"```([\w+-]*)", piece)[-1:] or [""]
            piece += "\n```"
            fence = "```" + lang[0] + "\n"
        else:
            fence = ""
        out.append(piece)
        text = text[cut:].lstrip("\n ")
    return out


def to_whatsapp(text: str) -> str:
    """Markdown → WhatsApp formatting (*bold*, _italic_, ~strike~, ```mono```)."""
    text = str(text or "")
    parts = re.split(r"(```[\s\S]*?```)", text)
    for index, part in enumerate(parts):
        if part.startswith("```"):
            parts[index] = re.sub(r"^```[\w+-]*\n?", "```", part)
            continue
        part = re.sub(r"^#{1,6}\s+(.+)$", r"*\1*", part, flags=re.M)
        part = re.sub(r"\*\*(.+?)\*\*", r"*\1*", part)
        part = re.sub(r"(?<![\w*])__(.+?)__(?![\w*])", r"_\1_", part)
        part = re.sub(r"~~(.+?)~~", r"~\1~", part)
        part = re.sub(r"\[([^\]]+)\]\((https?://[^)\s]+)\)", r"\1 (\2)", part)
        part = re.sub(r"^\s*[-*]\s+", "• ", part, flags=re.M)
        parts[index] = part
    return "".join(parts)


def numbered(card: "Card") -> List[Tuple[str, str, str, str]]:
    """Rows a reply number can pick on plain-text platforms: the choices, then paging buttons (``model:2``)."""
    rows = [(str(i + 1), c.label, c.value, c.description) for i, c in enumerate(card.choices[:10])]
    for button in (b for line in card.buttons for b in line):
        if ":" in button.id and len(rows) < 14:
            rows.append((str(len(rows) + 1), button.label, button.id, ""))
    return rows


def model_traits(row: Dict[str, Any], lang: str) -> str:
    """A short human description of a model for pickers: free · vision · reasoning."""
    traits = []
    if "free" in (row.get("badges") or []):
        traits.append(tr(lang, "бесплатная", "free"))
    if row.get("vision_state") == "yes":
        traits.append(tr(lang, "видит изображения", "vision"))
    if [level for level in row.get("reasoning_levels") or [] if level not in ("auto", "off")]:
        traits.append(tr(lang, "размышление", "reasoning"))
    return " · ".join(traits)


def short(text: str, size: int) -> str:
    text = re.sub(r"\s+", " ", str(text or "")).strip()
    return text if len(text) <= size else text[: max(1, size - 1)].rstrip() + "…"

# ---------------------------------------------------------------- the engine

COMMANDS = {
    "start": "menu", "menu": "menu", "help": "help", "new": "new", "chats": "chats", "chat": "chats", "model": "model",
    "models": "model", "settings": "settings", "stop": "stop", "regen": "regen", "retry": "regen", "temp": "temp",
    "status": "status", "pair": "pair", "web": "web", "think": "think", "persona": "persona", "lang": "lang",
    "меню": "menu", "помощь": "help", "новый": "new", "чаты": "chats", "модель": "model", "настройки": "settings",
    "стоп": "stop", "повтор": "regen", "статус": "status",
}


class Engine:
    """Commands, actions and chat for one adapter."""

    def __init__(self, adapter: Adapter) -> None:
        self.a = adapter
        self.p = adapter.platform
        self.running: Dict[str, Any] = {}

    # --- entry points -------------------------------------------------
    async def on_text(self, user_id: str, name: str, peer: str, text: str) -> None:
        from .pgdata import load_preferences
        prefs = load_preferences()
        lang = lang_of(self.p, prefs)
        text = str(text or "").strip()
        if not text:
            return
        command, arg = self._command(text)
        owner = (load_state().get(self.p) or {}).get("owner") or {}
        if command == "pair" or (not owner.get("id") and re.fullmatch(r"(pair[- ]?)?[A-Za-z0-9]{6}", text)):
            await self._pair(user_id, name, peer, arg if command == "pair" else re.sub(r"(?i)^pair[- ]?", "", text), lang)
            return
        if not is_allowed(self.p, user_id, prefs):
            await self.a.send(peer, Card(tr(lang, "Этот бот приватный. Чтобы подключиться, откройте MemuAI → Настройки → Мессенджеры и отправьте сюда код привязки: /pair КОД",
                                           "This bot is private. To connect, open MemuAI → Settings → Messengers and send the pairing code here: /pair CODE")))
            return
        st = user_state(self.p, user_id)
        pending = st.get("pending") if isinstance(st.get("pending"), dict) else {}
        if not command and re.fullmatch(r"\d{1,2}", text) and pending.get(text):
            await self.on_action(user_id, peer, pending[text])
            return
        if command:
            await self._run(command, arg, user_id, peer, prefs, lang)
            return
        await self.chat(user_id, peer, text, prefs, lang)

    async def on_action(self, user_id: str, peer: str, action: str, value: str = "") -> None:
        from .pgdata import load_preferences
        prefs = load_preferences()
        lang = lang_of(self.p, prefs)
        if not is_allowed(self.p, user_id, prefs):
            return
        name, _, arg = str(action or "").partition(":")
        if value:
            arg = value
        if name in ("menu", "help", "new", "settings", "status", "stop", "regen", "temp", "web", "think", "lang"):
            await self._run(name, arg, user_id, peer, prefs, lang)
        elif name == "chats":
            await self.show_chats(user_id, peer, lang, int(arg or 0) if str(arg or "0").isdigit() else 0)
        elif name == "chat":
            await self.open_chat(user_id, peer, arg, lang)
        elif name == "model":
            await self.show_models(user_id, peer, prefs, lang, int(arg or 0) if str(arg or "0").isdigit() else 0)
        elif name == "pick":
            await self.pick_model(user_id, peer, arg, prefs, lang)
        elif name == "persona":
            await self.show_personas(user_id, peer, prefs, lang, arg)

    # --- parsing ------------------------------------------------------
    @staticmethod
    def _command(text: str) -> Tuple[str, str]:
        match = re.match(r"^[/!]([\wа-яё]+)(?:@\S+)?\s*(.*)$", text, re.I | re.S)
        if not match:
            return "", ""
        return COMMANDS.get(match.group(1).lower(), ""), match.group(2).strip()

    async def _run(self, command: str, arg: str, user_id: str, peer: str, prefs: Dict[str, Any], lang: str) -> None:
        if command in ("menu", "help"):
            await self.a.send(peer, self.menu(user_id, prefs, lang, help_text=command == "help"))
        elif command == "new":
            save_user(self.p, user_id, chat="", temp_history=[], pending={})
            await self.a.send(peer, Card(tr(lang, "Новый чат. Напишите сообщение — он появится и в MemuAI.",
                                            "New chat. Send a message — it will appear in MemuAI too."),
                                         [[Button("model", tr(lang, "Модель", "Model")), Button("settings", tr(lang, "Настройки", "Settings"))]]))
        elif command == "chats":
            await self.show_chats(user_id, peer, lang, 0, query=arg)
        elif command == "model":
            if arg:
                await self.pick_model(user_id, peer, arg, prefs, lang, search=True)
            else:
                await self.show_models(user_id, peer, prefs, lang, 0)
        elif command == "settings":
            await self.a.send(peer, self.settings_card(user_id, prefs, lang))
        elif command == "status":
            await self.a.send(peer, self.status_card(user_id, prefs, lang))
        elif command == "stop":
            stopped = await self.stop(user_id)
            await self.a.send(peer, Card(tr(lang, "Остановлено." if stopped else "Сейчас ничего не выполняется.",
                                            "Stopped." if stopped else "Nothing is running.")))
        elif command == "regen":
            await self.chat(user_id, peer, "", prefs, lang, regenerate=True)
        elif command in ("temp", "web", "think"):
            await self.toggle(user_id, peer, command, arg, prefs, lang)
        elif command == "lang":
            from .pgdata import save_preferences
            value = arg.lower()[:2] if arg else ("ru" if lang == "en" else "en")
            value = "en" if value == "en" else "ru"
            save_preferences({f"{self.p}_language": value})
            await self.a.send(peer, self.settings_card(user_id, {**prefs, f"{self.p}_language": value}, value))
        elif command == "persona":
            await self.show_personas(user_id, peer, prefs, lang, arg)

    # --- cards --------------------------------------------------------
    def _model_name(self, model_id: str, prefs: Dict[str, Any]) -> str:
        from . import tgapp_chat
        for row in tgapp_chat.chat_models(prefs):
            if row["id"] == model_id:
                return str(row.get("name") or model_id)
        return model_id

    def _current_model(self, st: Dict[str, Any], prefs: Dict[str, Any]) -> str:
        from . import tgapp_chat
        return tgapp_chat.pick_model(str(st.get("model") or prefs.get(f"{self.p}_model") or ""), prefs)

    def _chat_title(self, chat_id: str) -> str:
        if not chat_id:
            return ""
        from .pgdata import load_chats
        from . import tgapp_chat
        active, _ = tgapp_chat.profiles()
        row = next((c for c in load_chats(active) if str(c.get("id")) == chat_id), None)
        return str((row or {}).get("title") or "")

    def menu(self, user_id: str, prefs: Dict[str, Any], lang: str, help_text: bool = False) -> Card:
        st = user_state(self.p, user_id)
        model = self._current_model(st, prefs)
        chat = tr(lang, "временный чат", "temporary chat") if st.get("temp") else (self._chat_title(st.get("chat") or "") or tr(lang, "новый чат", "new chat"))
        web = st.get("web") if st.get("web") is not None else bool(prefs.get("web_search"))
        lines = [f"**MemuAI**", tr(lang, f"Модель: {self._model_name(model, prefs) or 'нет'}", f"Model: {self._model_name(model, prefs) or 'none'}"),
                 tr(lang, f"Чат: {chat}", f"Chat: {chat}"),
                 tr(lang, f"Поиск в интернете: {'вкл' if web else 'выкл'}", f"Web search: {'on' if web else 'off'}")]
        if help_text:
            lines += ["", tr(lang, "Просто напишите сообщение — ответит MemuAI. Команды:", "Just send a message and MemuAI answers. Commands:"),
                      "/new · /chats · /model · /settings · /temp · /regen · /stop · /status"]
        return Card("\n".join(lines), [
            [Button("new", tr(lang, "Новый чат", "New chat"), "primary"), Button("chats", tr(lang, "Чаты", "Chats")),
             Button("model", tr(lang, "Модель", "Model"))],
            [Button("settings", tr(lang, "Настройки", "Settings")), Button("temp", tr(lang, "Временный", "Temporary")),
             Button("help", tr(lang, "Помощь", "Help"))]], title="MemuAI")

    def settings_card(self, user_id: str, prefs: Dict[str, Any], lang: str) -> Card:
        from . import personalities
        st = user_state(self.p, user_id)
        web = st.get("web") if st.get("web") is not None else bool(prefs.get("web_search"))
        think = st.get("think") if st.get("think") is not None else bool(prefs.get("thinking"))
        on, off = tr(lang, "вкл", "on"), tr(lang, "выкл", "off")
        persona = personalities.label(prefs.get("ai_personality"), lang)
        text = "\n".join([
            tr(lang, "**Настройки MemuAI**", "**MemuAI settings**"),
            tr(lang, f"Поиск в интернете: {on if web else off}", f"Web search: {on if web else off}"),
            tr(lang, f"Размышление: {on if think else off}", f"Reasoning: {on if think else off}"),
            tr(lang, f"Временный чат: {on if st.get('temp') else off}", f"Temporary chat: {on if st.get('temp') else off}"),
            tr(lang, f"Личность: {persona}", f"Personality: {persona}"),
            tr(lang, "Язык бота: русский", "Bot language: English"),
        ])
        return Card(text, [
            [Button("web", tr(lang, "Поиск", "Web search"), "success" if web else "secondary"),
             Button("think", tr(lang, "Размышление", "Reasoning"), "success" if think else "secondary"),
             Button("temp", tr(lang, "Временный", "Temporary"), "success" if st.get("temp") else "secondary")],
            [Button("persona", tr(lang, "Личность", "Personality")), Button("model", tr(lang, "Модель", "Model")),
             Button("lang", "English" if lang == "ru" else "Русский")],
            [Button("menu", tr(lang, "Меню", "Menu"))]], title=tr(lang, "Настройки", "Settings"))

    def status_card(self, user_id: str, prefs: Dict[str, Any], lang: str) -> Card:
        from . import tgapp_chat
        models = tgapp_chat.chat_models(prefs)
        st = user_state(self.p, user_id)
        busy = user_id in self.running
        text = "\n".join([tr(lang, "**Состояние MemuAI**", "**MemuAI status**"),
                          tr(lang, f"Доступно моделей: {len(models)}", f"Models available: {len(models)}"),
                          tr(lang, f"Модель: {self._model_name(self._current_model(st, prefs), prefs) or 'нет'}",
                             f"Model: {self._model_name(self._current_model(st, prefs), prefs) or 'none'}"),
                          tr(lang, "Сейчас отвечает" if busy else "Свободен", "Answering now" if busy else "Idle")])
        return Card(text, [[Button("menu", tr(lang, "Меню", "Menu"))]])

    async def show_chats(self, user_id: str, peer: str, lang: str, page: int = 0, query: str = "") -> None:
        from .pgdata import load_chats
        from . import tgapp_chat
        active, _ = tgapp_chat.profiles()
        rows = [c for c in load_chats(active) if isinstance(c, dict) and c.get("id") and (c.get("mode") or "chat") == "chat"]
        rows.sort(key=lambda c: (0 if c.get("pinned") else 1, -float(c.get("updated") or 0)))
        if query:
            q = query.lower()
            rows = [c for c in rows if q in str(c.get("title") or "").lower()]
        total = len(rows)
        page = max(0, min(page, max(0, (total - 1) // LIST_PAGE)))
        chunk = rows[page * LIST_PAGE:(page + 1) * LIST_PAGE]
        if not chunk:
            await self.a.send(peer, Card(tr(lang, "Чатов пока нет. Напишите сообщение — начнётся новый.", "No chats yet. Send a message to start one.")))
            return
        choices = [Choice(f"chat:{c['id']}", short(c.get("title") or tr(lang, "Без названия", "Untitled"), 60),
                          short(_last_text(c), 70)) for c in chunk]
        nav: List[Button] = []
        if page > 0:
            nav.append(Button(f"chats:{page - 1}", tr(lang, "Назад", "Back")))
        if (page + 1) * LIST_PAGE < total:
            nav.append(Button(f"chats:{page + 1}", tr(lang, "Дальше", "More")))
        nav.append(Button("new", tr(lang, "Новый чат", "New chat"), "primary"))
        await self._send_choice(user_id, peer, Card(tr(lang, f"**Чаты** · {total}", f"**Chats** · {total}"), [nav], choices,
                                                    "chat", tr(lang, "Выберите чат", "Pick a chat"), tr(lang, "Чаты", "Chats")), lang)

    async def open_chat(self, user_id: str, peer: str, chat_id: str, lang: str) -> None:
        from .pgdata import load_chats
        from . import tgapp_chat
        active, _ = tgapp_chat.profiles()
        row = next((c for c in load_chats(active) if str(c.get("id")) == chat_id), None)
        if not row:
            await self.a.send(peer, Card(tr(lang, "Чат не найден.", "Chat not found.")))
            return
        save_user(self.p, user_id, chat=chat_id, temp=False, temp_history=[], pending={})
        last = _last_text(row, role="assistant")
        text = tr(lang, f"Открыт чат «{short(row.get('title') or 'Без названия', 80)}».", f"Opened “{short(row.get('title') or 'Untitled', 80)}”.")
        if last:
            text += "\n\n" + tr(lang, "Последний ответ:", "Last answer:") + "\n" + short(last, 600)
        await self.a.send(peer, Card(text, [[Button("new", tr(lang, "Новый чат", "New chat")), Button("chats", tr(lang, "Чаты", "Chats"))]]))

    async def show_models(self, user_id: str, peer: str, prefs: Dict[str, Any], lang: str, page: int = 0) -> None:
        from . import tgapp_chat
        rows = tgapp_chat.chat_models(prefs)
        if not rows:
            await self.a.send(peer, Card(tr(lang, "Нет доступных моделей: добавьте аккаунт в MemuAI Proxy.", "No models available: add an account in MemuAI Proxy.")))
            return
        st = user_state(self.p, user_id)
        current = self._current_model(st, prefs)
        total = len(rows)
        page = max(0, min(page, (total - 1) // LIST_PAGE))
        chunk = rows[page * LIST_PAGE:(page + 1) * LIST_PAGE]
        choices = [Choice(f"pick:{r['id']}", short(("● " if r["id"] == current else "") + str(r.get("name") or r["id"]), 60),
                          model_traits(r, lang)) for r in chunk]
        nav: List[Button] = []
        if page > 0:
            nav.append(Button(f"model:{page - 1}", tr(lang, "Назад", "Back")))
        if (page + 1) * LIST_PAGE < total:
            nav.append(Button(f"model:{page + 1}", tr(lang, "Дальше", "More")))
        nav.append(Button("menu", tr(lang, "Меню", "Menu")))
        text = tr(lang, f"**Модель** · сейчас: {self._model_name(current, prefs)}\nПоиск: /model название", f"**Model** · now: {self._model_name(current, prefs)}\nSearch: /model name")
        await self._send_choice(user_id, peer, Card(text, [nav], choices, "pick", tr(lang, "Выберите модель", "Pick a model"), tr(lang, "Модели", "Models")), lang)

    async def pick_model(self, user_id: str, peer: str, query: str, prefs: Dict[str, Any], lang: str, search: bool = False) -> None:
        from . import tgapp_chat
        rows = tgapp_chat.chat_models(prefs)
        exact = next((r for r in rows if r["id"] == query), None)
        if exact is None and search:
            q = query.lower()
            found = [r for r in rows if q in r["id"].lower() or q in str(r.get("name") or "").lower()]
            if len(found) == 1:
                exact = found[0]
            elif found:
                choices = [Choice(f"pick:{r['id']}", short(str(r.get("name") or r["id"]), 60), model_traits(r, lang)) for r in found[:LIST_PAGE]]
                await self._send_choice(user_id, peer, Card(tr(lang, f"Нашлось моделей: {len(found)}", f"Models found: {len(found)}"), [], choices, "pick",
                                                            tr(lang, "Выберите модель", "Pick a model")), lang)
                return
        if exact is None:
            await self.a.send(peer, Card(tr(lang, "Такой модели нет. Список: /model", "No such model. List: /model")))
            return
        save_user(self.p, user_id, model=exact["id"], pending={})
        await self.a.send(peer, Card(tr(lang, f"Модель: **{exact.get('name') or exact['id']}**", f"Model: **{exact.get('name') or exact['id']}**"),
                                     [[Button("menu", tr(lang, "Меню", "Menu"))]]))

    async def show_personas(self, user_id: str, peer: str, prefs: Dict[str, Any], lang: str, pick: str = "") -> None:
        from . import personalities
        from .pgdata import save_preferences
        catalog = personalities.catalog(lang)
        ids = {row["id"] for row in catalog["items"]}
        if pick and pick in ids:
            save_preferences({"ai_personality": pick})
            await self.a.send(peer, Card(tr(lang, f"Личность MemuAI: **{personalities.label(pick, lang)}**", f"MemuAI personality: **{personalities.label(pick, lang)}**"),
                                         [[Button("settings", tr(lang, "Настройки", "Settings"))]]))
            return
        current = personalities.normalize(prefs.get("ai_personality"))
        items = catalog["items"]
        try:
            page = max(0, int(pick or 0))
        except ValueError:
            page = 0
        page = min(page, (len(items) - 1) // LIST_PAGE)
        chunk = items[page * LIST_PAGE:(page + 1) * LIST_PAGE]
        choices = [Choice(f"persona:{r['id']}", short(("● " if r["id"] == current else "") + r["name"], 60), short(r["description"], 70)) for r in chunk]
        nav: List[Button] = []
        if page > 0:
            nav.append(Button(f"persona:{page - 1}", tr(lang, "Назад", "Back")))
        if (page + 1) * LIST_PAGE < len(items):
            nav.append(Button(f"persona:{page + 1}", tr(lang, "Дальше", "More")))
        nav.append(Button("settings", tr(lang, "Настройки", "Settings")))
        await self._send_choice(user_id, peer, Card(tr(lang, f"**Личность** · сейчас: {personalities.label(current, lang)}", f"**Personality** · now: {personalities.label(current, lang)}"),
                                                    [nav], choices, "persona", tr(lang, "Выберите личность", "Pick a personality"), tr(lang, "Личности", "Personalities")), lang)

    async def _send_choice(self, user_id: str, peer: str, card: Card, lang: str) -> None:
        """Remember numbers for platforms without native lists (a reply «3» picks the third row)."""
        pending = {number: value for number, _, value, _ in numbered(card)}
        save_user(self.p, user_id, pending=pending)
        await self.a.send(peer, card)

    async def toggle(self, user_id: str, peer: str, key: str, arg: str, prefs: Dict[str, Any], lang: str) -> None:
        st = user_state(self.p, user_id)
        if key == "temp":
            current = bool(st.get("temp"))
        else:
            current = st.get(key) if st.get(key) is not None else bool(prefs.get("web_search" if key == "web" else "thinking"))
        value = (arg.lower() in ("on", "1", "yes", "вкл", "да")) if arg else not current
        if key == "temp":
            save_user(self.p, user_id, temp=value, temp_history=[], chat="" if value else st.get("chat", ""))
        else:
            save_user(self.p, user_id, **{key: value})
        await self.a.send(peer, self.settings_card(user_id, prefs, lang))

    async def stop(self, user_id: str) -> bool:
        from . import tgapp_chat
        job = self.running.get(user_id)
        if job is None:
            return False
        return await tgapp_chat.cancel_job(job)

    # --- chat ---------------------------------------------------------
    async def chat(self, user_id: str, peer: str, text: str, prefs: Dict[str, Any], lang: str, regenerate: bool = False) -> None:
        from . import tgapp_chat
        if user_id in self.running:
            await self.a.send(peer, Card(tr(lang, "Подождите, MemuAI ещё отвечает. Остановить: /stop", "MemuAI is still answering. Stop it: /stop"),
                                         [[Button("stop", tr(lang, "Стоп", "Stop"), "danger")]]))
            return
        st = user_state(self.p, user_id)
        active, _ = tgapp_chat.profiles()
        temp = bool(st.get("temp"))
        try:
            job = tgapp_chat.start_send(owner=f"{self.p}:{user_id}", profile_id=active, chat_id="" if temp else str(st.get("chat") or ""),
                                        text=text, attachments=[], model=str(st.get("model") or prefs.get(f"{self.p}_model") or ""),
                                        web_search=st.get("web"), thinking=st.get("think"), temp=temp, meme_id="",
                                        regenerate=regenerate, temp_history=st.get("temp_history") if temp else None, lang=lang, via=self.p)
        except ValueError as exc:
            if "не найден" in str(exc) or "not found" in str(exc):
                save_user(self.p, user_id, chat="")
            await self.a.send(peer, Card(str(exc)))
            return
        self.running[user_id] = job
        try:
            await self._stream(job, user_id, peer, text, lang, temp)
        finally:
            self.running.pop(user_id, None)

    async def _stream(self, job: Any, user_id: str, peer: str, text: str, lang: str, temp: bool) -> None:
        offset, shown, final, error, chat_id, stopped = 0, "", "", "", "", False
        await self.a.typing(peer)
        message_id: Optional[str] = None
        last_edit = 0.0
        last_typing = time.monotonic()
        while True:
            events = await job.wait(offset, 1.0)
            offset += len(events)
            for event in events:
                kind = event.get("type")
                if kind == "start":
                    chat_id = str(event.get("chat_id") or "")
                elif kind == "delta":
                    shown += str(event.get("text") or "")
                elif kind == "message":
                    final = str((event.get("message") or {}).get("content") or "")
                elif kind == "error":
                    error = str(event.get("message") or "")
                elif kind == "done":
                    stopped = bool(event.get("stopped"))
                    chat_id = str(event.get("chat_id") or chat_id)
            now = time.monotonic()
            if self.a.can_edit and shown and now - last_edit > STREAM_EDIT_SECONDS and not job.done:
                preview = shown[-(self.a.limit - 40):] if len(shown) > self.a.limit - 40 else shown
                card = Card(preview + " ▌", [[Button("stop", tr(lang, "Стоп", "Stop"), "danger")]])
                if message_id is None:
                    message_id = await self.a.send(peer, card)
                else:
                    await self.a.edit(peer, message_id, card)
                last_edit = now
            elif not self.a.can_edit and now - last_typing > 6 and not job.done:
                await self.a.typing(peer)
                last_typing = now
            if job.done:
                break
        from . import tgapp_chat
        answer = tgapp_chat.clean_answer(final or shown).strip()
        if temp and answer and not error:
            st = user_state(self.p, user_id)
            history = list(st.get("temp_history") or [])
            if text:
                history.append({"role": "user", "content": text})
            history.append({"role": "assistant", "content": answer})
            save_user(self.p, user_id, temp_history=history)
        elif chat_id and not temp and not error:
            save_user(self.p, user_id, chat=chat_id)
        if error and not answer:
            body = tr(lang, "Ошибка: ", "Error: ") + error
        else:
            body = answer or tr(lang, "(пустой ответ)", "(empty answer)")
            if stopped:
                body += "\n\n_" + tr(lang, "остановлено", "stopped") + "_"
        pieces = split_text(body, self.a.limit)
        buttons = [[Button("regen", tr(lang, "Ещё раз", "Regenerate")), Button("new", tr(lang, "Новый чат", "New chat")),
                    Button("menu", tr(lang, "Меню", "Menu"))]]
        for index, piece in enumerate(pieces):
            card = Card(piece, buttons if index == len(pieces) - 1 else [])
            if index == 0 and message_id is not None:
                if not await self.a.edit(peer, message_id, card):
                    await self.a.send(peer, card)
            else:
                await self.a.send(peer, card)

    async def _pair(self, user_id: str, name: str, peer: str, code: str, lang: str) -> None:
        owner = (load_state().get(self.p) or {}).get("owner") or {}
        if owner.get("id") and str(owner["id"]) == str(user_id):
            from .pgdata import load_preferences
            await self.a.send(peer, self.menu(user_id, load_preferences(), lang))
            return
        if owner.get("id"):
            await self.a.send(peer, Card(tr(lang, "Этот бот уже привязан к другому человеку.", "This bot is already paired with someone else.")))
            return
        ok, reason = try_pair(self.p, user_id, name, code)
        if ok:
            from .pgdata import load_preferences
            await self.a.send(peer, Card(tr(lang, "Готово: MemuAI привязан. Напишите сообщение или откройте меню.", "Done: MemuAI is paired. Send a message or open the menu.")))
            await self.a.send(peer, self.menu(user_id, load_preferences(), lang, help_text=True))
            return
        text = {"expired": tr(lang, "Код устарел. Получите новый в MemuAI → Настройки → Мессенджеры.", "The code has expired. Get a new one in MemuAI → Settings → Messengers."),
                "locked": tr(lang, "Слишком много попыток. Получите новый код в MemuAI.", "Too many attempts. Get a new code in MemuAI."),
                }.get(reason, tr(lang, "Код не подошёл.", "The code is wrong."))
        await self.a.send(peer, Card(text))


def _last_text(chat: Dict[str, Any], role: str = "") -> str:
    for row in reversed(chat.get("messages") or []):
        if isinstance(row, dict) and (not role or row.get("role") == role) and row.get("role") in ("user", "assistant"):
            content = row.get("content")
            if isinstance(content, str) and content.strip():
                return content
    return ""


def verify_signature(secret: str, body: bytes, header: str) -> bool:
    """``X-Hub-Signature-256: sha256=<hex>`` of a Meta webhook."""
    if not secret or not header or not header.startswith("sha256="):
        return False
    expected = hmac.new(secret.encode("utf-8"), body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, header.split("=", 1)[1].strip())
